{% extends 'parts/report.sql' %}
{% set min_score = args.min_score %}
{% block columns %}team, count(*) AS players, {{ super() }}{% endblock %}
{% block where %}{% include 'parts/filters.sql' %}{% endblock %}
{% block rest %}GROUP BY team ORDER BY team{% endblock %}

{% import 'parts/helpers.sql' as h %}
{% set ns = namespace(counted=[]) %}
{% set columns %}
{% for team in args.teams | sort if team != 'green' %}
  {% do ns.counted.append(team) %}
  {{ h.count_if('team', team) }} AS {{ team }},
{% endfor %}
{% endset %}
{% include 'parts/players.sql' +%}
SELECT {{ columns }}
       {% call h.column('all_players') %}count(*){% endcall %},
       {{ ns.counted | map('upper') | join('/') | sql_quote }} AS counted,
       {{ '%d team(s)' | format(ns.counted | length) | sql_quote }} AS teams
FROM players

{% set ranks = [{'name': 'gold', 'min': 80}, {'name': 'silver', 'min': 50},
                {'name': 'bronze', 'min': 0}] %}
{% include 'parts/players.sql' +%}
SELECT CASE
  {% for r in ranks | sort(attribute='min', reverse=true) %}
  WHEN score >= {{ r.min }} THEN {{ r.name | title | sql_quote }}
  {% endfor %}
  END AS rank, count(*) AS players
FROM players
GROUP BY rank
ORDER BY min(score) DESC

